// TenantPolicy ADR-0035, ADR-0055. allowed_methods needs at least one of password, passkey, otp_email, otp_sms, magic_link.
type TenantPolicy struct {
	AllowedMethods []TenantPolicyAllowedMethods `json:"allowed_methods"`

	// Captcha When Turnstile challenges are asked (ADR-0076); omitted keeps the current setting
	Captcha *struct {
		// AccountFailures Below lockout.threshold
		AccountFailures *int  `json:"account_failures,omitempty"`
		Enabled         *bool `json:"enabled,omitempty"`
		IpFailures      *int  `json:"ip_failures,omitempty"`
	} `json:"captcha,omitempty"`

	// Compliance Omitted keeps the stored setting (ADR-0102)
	Compliance *struct {
		// MonthlyPack Store last month's compliance pack on the 1st; needs audit archive storage, else 422
		MonthlyPack *bool `json:"monthly_pack,omitempty"`
	} `json:"compliance,omitempty"`
	DeletionGraceDays int `json:"deletion_grace_days"`

	// DpopNonce Require a server-issued DPoP-Nonce in every proof (RFC 9449 §8); off by default (ADR-0095)
	DpopNonce *bool `json:"dpop_nonce,omitempty"`

	// Governance Omitted keeps the stored setting; every name must be an existing role or declared permission, else 422 (ADR-0110)
	Governance *struct {
		// ProtectedPermissions Allowing these directly needs a second admin's approval
		ProtectedPermissions *[]string `json:"protected_permissions,omitempty"`

		// ProtectedRoles Granting these needs a second admin's approval
		ProtectedRoles *[]string `json:"protected_roles,omitempty"`

		// RequestablePermissions Users may request an allow on these for 15–480 minutes
		RequestablePermissions *[]string `json:"requestable_permissions,omitempty"`

		// RequestableRoles Users may request these for 15–480 minutes
		RequestableRoles *[]string `json:"requestable_roles,omitempty"`
	} `json:"governance,omitempty"`
	Lockout struct {
		BaseSec   int `json:"base_sec"`
		MaxSec    int `json:"max_sec"`
		Threshold int `json:"threshold"`
	} `json:"lockout"`
	Mfa TenantPolicyMfa `json:"mfa"`

	// MfaPush Omitted keeps the stored setting (ADR-0111)
	MfaPush *struct {
		// Enabled Offer push approval at the second-factor step
		Enabled *bool `json:"enabled,omitempty"`
	} `json:"mfa_push,omitempty"`

	// Otp ADR-0041
	Otp struct {
		AllowedCountries       []string `json:"allowed_countries"`
		PerIdentifierPerHour   int      `json:"per_identifier_per_hour"`
		PerIpPerHour           int      `json:"per_ip_per_hour"`
		RequireKnownIdentifier bool     `json:"require_known_identifier"`
		SenderId               string   `json:"sender_id"`
		SmsEnabled             bool     `json:"sms_enabled"`
	} `json:"otp"`

	// Passkey Passkey rules; omitted keeps the stored ones (ADR-0104, ADR-0117)
	Passkey *struct {
		// Authenticators Authenticator models by AAGUID (ADR-0117): allow accepts only attested passkeys of listed models; deny refuses attested passkeys of listed models; with either, models FIDO metadata reports revoked or compromised are refused. Checked at registration and sign-in.
		Authenticators *struct {
			Aaguids *[]openapi_types.UUID                  `json:"aaguids,omitempty"`
			Mode    *TenantPolicyPasskeyAuthenticatorsMode `json:"mode,omitempty"`
		} `json:"authenticators,omitempty"`

		// RequireDeviceBound Refuse passkeys that may sync to other devices, at registration and sign-in
		RequireDeviceBound *bool `json:"require_device_bound,omitempty"`
	} `json:"passkey,omitempty"`
	Password struct {
		CheckBreached bool `json:"check_breached"`
		MaxLength     int  `json:"max_length"`
		MinLength     int  `json:"min_length"`
	} `json:"password"`

	// Risk Sign-in risk bands (ADR-0069); omitted = enabled, step_up 40, block 80
	Risk *struct {
		// AllowEmailDomains Domains (and their subdomains) the disposable-email list doesn't count (ADR-0113)
		AllowEmailDomains *[]string `json:"allow_email_domains,omitempty"`

		// Block Score at which sign-in is refused; above step_up; 101 never blocks
		Block   *int  `json:"block,omitempty"`
		Enabled *bool `json:"enabled,omitempty"`

		// ExemptAsns Networks never counted as hosting or new, such as the company's VPN; not also in hosting_asns (ADR-0120)
		ExemptAsns *[]int `json:"exempt_asns,omitempty"`

		// HostingAsns Networks (AS numbers) this tenant adds to the hosting list (ADR-0120)
		HostingAsns *[]int `json:"hosting_asns,omitempty"`

		// StepUp Score at which a second factor is required
		StepUp *int `json:"step_up,omitempty"`

		// Weights Points per signal, 0-100; omitted signals keep the defaults (new_device 30, new_country 25, fast_country_change 35, account_failures 15, ip_failures 20, tor_exit 40, push_reported 40, velocity_account 25, velocity_network 35, shared_device 30, disposable_email 60, signup_burst_network 40, signup_burst_country 30, new_network 15, hosting_network 25, impossible_travel 45); 0 turns a signal off (ADR-0101, ADR-0116)
		Weights *struct {
			AccountFailures    *int `json:"account_failures,omitempty"`
			DisposableEmail    *int `json:"disposable_email,omitempty"`
			FastCountryChange  *int `json:"fast_country_change,omitempty"`
			HostingNetwork     *int `json:"hosting_network,omitempty"`
			ImpossibleTravel   *int `json:"impossible_travel,omitempty"`
			IpFailures         *int `json:"ip_failures,omitempty"`
			NewCountry         *int `json:"new_country,omitempty"`
			NewDevice          *int `json:"new_device,omitempty"`
			NewNetwork         *int `json:"new_network,omitempty"`
			PushReported       *int `json:"push_reported,omitempty"`
			SharedDevice       *int `json:"shared_device,omitempty"`
			SignupBurstCountry *int `json:"signup_burst_country,omitempty"`
			SignupBurstNetwork *int `json:"signup_burst_network,omitempty"`
			TorExit            *int `json:"tor_exit,omitempty"`
			VelocityAccount    *int `json:"velocity_account,omitempty"`
			VelocityNetwork    *int `json:"velocity_network,omitempty"`
		} `json:"weights,omitempty"`
	} `json:"risk,omitempty"`
	Session struct {
		AbsoluteSec int `json:"absolute_sec"`
		IdleSec     int `json:"idle_sec"`
	} `json:"session"`

	// SocialSignup A first Google or Apple sign-in creates the account (ADR-0055); default true
	SocialSignup    *bool `json:"social_signup,omitempty"`
	StepUpMaxAgeSec *int  `json:"step_up_max_age_sec,omitempty"`
	TrustDeviceDays *int  `json:"trust_device_days,omitempty"`
}

